from copy import deepcopy


def sort_assets(items, field, descending=False):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not isinstance(field, str):
        raise TypeError("field must be a string")
    if not field:
        raise ValueError("field must not be empty")
    if not isinstance(descending, bool):
        raise TypeError("descending must be a bool")
    for item in items:
        if not isinstance(item, dict):
            raise TypeError("every item must be a dictionary")
        if field not in item:
            raise ValueError("an item is missing the sort field")
    result = items
    try:
        result.sort(key=lambda item: item[field], reverse=descending)
    except TypeError as exc:
        raise ValueError("field values are not mutually comparable") from exc
    return result
```

